import usage from "@/content/token-usage.json";

const fullNumber = new Intl.NumberFormat("en-CA");
const compact = new Intl.NumberFormat("en-CA", { notation: "compact", maximumFractionDigits: 1 });
const date = (iso: string) =>
  new Date(`${iso}T12:00:00Z`).toLocaleDateString("en-CA", { month: "short", day: "numeric", year: "numeric", timeZone: "UTC" });

export const tokenSummary = () =>
  `${compact.format(usage.total)} tokens through Claude Code, Codex and Grok since ${date(usage.since)}`;

/** All-time token count from my coding agents, generated by `pnpm tokens` from T3 Code's usage cache. */
export function TokenCounter({ className = "" }: { className?: string }) {
  const providers = Object.keys(usage.providers).join(", ").replace(/, ([^,]*)$/, " and $1");
  return (
    <section aria-labelledby="token-counter" className={`rounded-md border border-rurikon-border px-4 py-3 ${className}`}>
      <h2 id="token-counter" className="text-[0.85em] text-rurikon-400">
        Tokens through my coding agents
      </h2>
      <p className="mt-1 font-semibold text-rurikon-700 tabular-nums text-[1.5em] leading-tight">
        <data value={usage.total}>{fullNumber.format(usage.total)}</data>
      </p>
      <p className="mt-1 text-[0.85em] text-rurikon-400">
        {compact.format(usage.total)} tokens across {fullNumber.format(usage.messages)} agent messages in {providers},
        since {date(usage.since)}. Most of it is context the agents re-read each step; they wrote{" "}
        {compact.format(usage.output)} tokens of output. Updated {date(usage.asOf)}.
      </p>
    </section>
  );
}
